using System;using System.Collections.Generic;using System.IO;using System.Linq;
namespace SlopProX {
 public sealed class TimingMarker {public double SourceSeconds,TargetSeconds,Strength;}
 public sealed class TimingAnalysis {
  public float[] Samples;public int Rate,Channels;public double DetectedTempo,Confidence;public List<TimingMarker> Markers=new List<TimingMarker>();public double Duration{get{return Samples.Length/(double)(Rate*Channels);}}
  public static TimingAnalysis Analyze(string file,double offset,double duration){var wave=CachedAudio.Load(file);int first=(int)Math.Max(0,Math.Min(wave.Frames,Math.Round(offset*wave.Rate))),frames=(int)Math.Max(0,Math.Min(wave.Frames-first,Math.Round(duration*wave.Rate)));if(frames<wave.Rate/8)throw new InvalidDataException("Audio selection is too short for timing analysis.");var a=new TimingAnalysis{Rate=wave.Rate,Channels=wave.Channels,Samples=new float[frames*wave.Channels]};Array.Copy(wave.Samples,first*wave.Channels,a.Samples,0,a.Samples.Length);
   int hop=Math.Max(32,wave.Rate/250),window=hop*2;var energy=new List<double>();for(int at=0;at<frames;at+=hop){double sum=0;int last=Math.Min(frames,at+window);for(int i=at;i<last;i++){double v=0;for(int c=0;c<a.Channels;c++)v+=a.Samples[i*a.Channels+c]*a.Samples[i*a.Channels+c];sum+=v/a.Channels;}energy.Add(sum/Math.Max(1,last-at));}
   double maximum=energy.Max(),floor=Math.Max(.000001,maximum*.008);int lastMarker=-wave.Rate;
   for(int i=1;i<energy.Count-2;i++){double novelty=Math.Max(0,energy[i]-energy[i-1]),background=0;for(int k=Math.Max(0,i-12);k<i;k++)background+=energy[k];background/=Math.Min(12,i);if(energy[i]<floor||novelty<Math.Max(floor*.4,background*.65)||energy[i]<energy[i+1]*.6)continue;
    int left=Math.Max(0,(i-2)*hop),right=Math.Min(frames,(i+2)*hop);float peak=0;for(int f=left;f<right;f++)for(int c=0;c<a.Channels;c++)peak=Math.Max(peak,Math.Abs(a.Samples[f*a.Channels+c]));int onset=left;for(int f=left;f<right;f++){float value=0;for(int c=0;c<a.Channels;c++)value=Math.Max(value,Math.Abs(a.Samples[f*a.Channels+c]));if(value>peak*.14){onset=f;break;}}
    if(onset-lastMarker<wave.Rate*.055)continue;lastMarker=onset;a.Markers.Add(new TimingMarker{SourceSeconds=onset/(double)wave.Rate,TargetSeconds=onset/(double)wave.Rate,Strength=novelty/Math.Max(floor,energy[i])});if(a.Markers.Count>=8192)break;
   }
   var histogram=new double[601];double total=0;for(int i=0;i<a.Markers.Count;i++)for(int j=i+1;j<Math.Min(a.Markers.Count,i+5);j++){double dt=a.Markers[j].SourceSeconds-a.Markers[i].SourceSeconds;if(dt<.15||dt>3)continue;double bpm=60*(j-i)/dt;while(bpm<70)bpm*=2;while(bpm>180)bpm/=2;int bin=(int)Math.Round(bpm*3);double weight=(j-i)*(j-i);if(bin>=0&&bin<histogram.Length){histogram[bin]+=weight;total+=weight;}}
   int best=0;double bestSum=0;for(int i=210;i<=540;i++){double sum=0;for(int k=Math.Max(0,i-2);k<=Math.Min(600,i+2);k++)sum+=histogram[k];if(sum>bestSum){bestSum=sum;best=i;}}a.DetectedTempo=best==0?120:best/3.0;a.Confidence=total==0?0:Math.Min(1,bestSum/total);return a;
  }
  public List<TimingMarker> Map(double sourceTempo,double targetTempo,double gridBeats,double amount){if(sourceTempo<20||sourceTempo>400||targetTempo<20||targetTempo>400||gridBeats<=0||amount<0||amount>1)throw new ArgumentException("Invalid timing map.");double ratio=sourceTempo/targetTempo;var map=new List<TimingMarker>{new TimingMarker{SourceSeconds=0,TargetSeconds=0}};foreach(var marker in Markers){if(marker.SourceSeconds<.005||marker.SourceSeconds>Duration-.005)continue;double musical=marker.SourceSeconds*sourceTempo/60,raw=marker.SourceSeconds*ratio,snapped=Math.Round(musical/gridBeats)*gridBeats*60/targetTempo,target=raw+(snapped-raw)*amount;var previous=map[map.Count-1];if(target<=previous.TargetSeconds+.002||marker.SourceSeconds<=previous.SourceSeconds+.002||target>=Duration*ratio-.002)continue;double stretch=(target-previous.TargetSeconds)/(marker.SourceSeconds-previous.SourceSeconds);if(stretch<.4||stretch>2.5)target=previous.TargetSeconds+(marker.SourceSeconds-previous.SourceSeconds)*ratio;map.Add(new TimingMarker{SourceSeconds=marker.SourceSeconds,TargetSeconds=target,Strength=marker.Strength});}map.Add(new TimingMarker{SourceSeconds=Duration,TargetSeconds=Duration*ratio});return map;}
  // Stereo-linked waveform-similarity overlap-add. Matching shifts complete grains; it does not resample pitch.
  public float[] Render(IList<TimingMarker> map){if(map==null||map.Count<2)throw new ArgumentException("No timing map.");int frames=(int)Math.Round(map[map.Count-1].TargetSeconds*Rate);if(frames<1||frames>Rate*300)throw new InvalidDataException("Timing output exceeds 300 seconds.");var result=new float[frames*Channels];for(int i=0;i<map.Count-1;i++){int a=(int)Math.Round(map[i].SourceSeconds*Rate),b=(int)Math.Round(map[i+1].SourceSeconds*Rate),x=(int)Math.Round(map[i].TargetSeconds*Rate),y=(int)Math.Round(map[i+1].TargetSeconds*Rate);if(a<0||b<=a||b>Samples.Length/Channels||x<0||y<=x||y>frames)throw new InvalidDataException("Timing markers must be strictly ordered.");Stretch(a,b,x,y,result);}return result;}
  private void Stretch(int first,int last,int destFirst,int destLast,float[] output){int inputLength=last-first,length=destLast-destFirst;if(inputLength==length){Array.Copy(Samples,first*Channels,output,destFirst*Channels,length*Channels);return;}if(inputLength<64||length<64){for(int f=0;f<length;f++){double source=first+f*inputLength/(double)length;int a=Math.Min(last-1,(int)source),b=Math.Min(last-1,a+1);float frac=(float)(source-a);for(int c=0;c<Channels;c++)output[(destFirst+f)*Channels+c]=Samples[a*Channels+c]*(1-frac)+Samples[b*Channels+c]*frac;}return;}
   int window=Math.Min(Math.Max(128,Rate*30/1000),inputLength),hop=Math.Max(32,window/3),overlap=Math.Min(window-hop,Rate/100),search=Math.Min(Rate*8/1000,inputLength/5);double ratio=length/(double)inputLength;var sum=new float[length*Channels];var weight=new float[length];int previous=first;
   for(int dest=0,grain=0;dest<length;dest+=hop,grain++){int expected=Math.Min(last-window,Math.Max(first,first+(int)Math.Round(dest/ratio))),chosen=expected;
    if(grain>0&&overlap>24){double best=-2;int reference=Math.Min(last-overlap,previous+hop),low=Math.Max(first,expected-search),high=Math.Min(last-window,expected+search);for(int candidate=low;candidate<=high;candidate+=4){double dot=0,ea=1e-12,eb=1e-12;for(int j=0;j<overlap;j+=8){for(int c=0;c<Channels;c++){double va=Samples[(reference+j)*Channels+c],vb=Samples[(candidate+j)*Channels+c];dot+=va*vb;ea+=va*va;eb+=vb*vb;}}double score=dot/Math.Sqrt(ea*eb)-.01*Math.Abs(candidate-expected)/Math.Max(1,search);if(score>best){best=score;chosen=candidate;}}}
    previous=chosen;for(int j=0;j<window&&dest+j<length;j++){float w=(float)(.5-.5*Math.Cos(2*Math.PI*(j+.5)/window));weight[dest+j]+=w;for(int c=0;c<Channels;c++)sum[(dest+j)*Channels+c]+=Samples[(chosen+j)*Channels+c]*w;}
   }
   for(int f=0;f<length;f++)for(int c=0;c<Channels;c++)output[(destFirst+f)*Channels+c]=weight[f]>1e-10?sum[f*Channels+c]/weight[f]:0;
  }
  public void Save(string path,IList<TimingMarker> map){var data=Render(map);using(var writer=new ExportWaveWriter(path,Rate,Channels,24,false))writer.Write(data,0,data.Length);}
 }
}
